    slogan:'किसी विशिष्ट फ़ाइल एक्सटेंशन के राइट-क्लिक मेन्यू का प्रबंधन करें। स्कैन करने के लिए एक एक्सटेंशन दर्ज करें (उदा. .txt / .jpg / .zip); आइटम चार रजिस्ट्री रूट से एकत्र होते हैं: एक्सटेंशन कुंजी, इसका ProgID, SystemFileAssociations\\.ext, और अनुमानित प्रकार। टॉगल करना प्रतिवर्ती है (verbs के लिए LegacyDisable, हैंडलर के लिए कुंजी स्थानांतरण); कस्टम आइटम वर्तमान उपयोगकर्ता में लिखे जाते हैं, पहले स्वचालित बैकअप के साथ।',
