// ============================================================
//  Windows 内建项友好名映射（跟随当前语言兜底）。
//  后端已尽力从注册表解析真实 label，但有些 Windows 内建项注册表里只有裸键名
//  （如 find / removeproperties）或英文 COM 描述，系统没给本地化名。这里按
//  id / label 兜底补一层。只收录确属 Windows 内建的项；第三方无法穷举。
//  未列出的语言回退 en。
// ============================================================
